/* BIOS Boot Screen */
.bios-boot-screen {
  position: fixed;
  inset: 0;
  background: #000;
  color: #c0c0c0;
  font-family: var(--mono);
  font-size: 14px;
  line-height: 1.6;
  z-index: 99999;
